WITH cleaned AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, UPPER(txn_type) AS txn_type_upper, COALESCE(amount, 0) AS amount_filled, COALESCE(merchant, 'DIRECT') AS resolved_merchant FROM transactions WHERE txn_time > TO_TIMESTAMP('2023-08-05 08:00:00') AND merchant IS DISTINCT FROM 'Amazon') SELECT id, amount, merchant, AVG(amount) OVER (PARTITION BY txn_type, merchant ORDER BY amount ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY amount DESC, id ASC) AS event_seq, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY amount DESC, id ASC) AS event_seq_2, PERCENT_RANK() OVER (PARTITION BY txn_type ORDER BY amount_filled DESC NULLS LAST) AS amount_filled_percent_rank FROM cleaned
